ST.xhtml:p:
(*电压转为UNIT输出*)
RTrigge(CLK := bDAOutputVolEnable);
RTrigge2(CLK := bDAOutputVolCloseEnable);
IF RTrigge.Q THEN
  bDAOutputVolEnable := FALSE;
  g_bDAOutputVolEnable:=TRUE;
  DAOutputVolAna := LREAL_TO_UINT((32767.0 / 10.0) * DAOutputVol);

  g_boMasterValve := TRUE;
  g_uoSharePressureOut := DAOutputVolAna;
  g_uoMasterPressureOut := DAOutputVolAna;
  CASE gas_type OF
    0:
      g_boAirValve:= TRUE;
      g_boOxygenValve := FALSE;
      g_boNirtogenValve := FALSE;
      g_uoAirPressureOut := DAOutputVolAna;
      g_uoNirtogenPressureOut := 0;
      g_uoOxygenPressureOut := 0;

    1:
      g_boOxygenValve := TRUE;
      g_boAirValve:= FALSE;
      g_boNirtogenValve := FALSE;
      g_uoOxygenPressureOut := DAOutputVolAna;
      g_uoAirPressureOut := 0;
      g_uoNirtogenPressureOut := 0;
    2:
      g_boOxygenValve := FALSE;
      g_boNirtogenValve := TRUE;
      g_boAirValve:= FALSE;
      g_uoOxygenPressureOut := 0;
      g_uoAirPressureOut := 0;
      g_uoNirtogenPressureOut := DAOutputVolAna;
  END_CASE;
END_IF;

IF RTrigge2.Q THEN
  bDAOutputVolCloseEnable :=FALSE;
  g_boMasterValve := FALSE;
  g_boOxygenValve := FALSE;
  g_boOxygenValve := FALSE;
  g_boNirtogenValve := FALSE;
  g_uoMasterPressureOut := 0;
  g_uoAirPressureOut := 0;
  g_uoOxygenPressureOut := 0;
  g_uoNirtogenPressureOut := 0;
  g_uoSharePressureOut := 0;    
  g_bDAOutputVolEnable:=FALSE;
END_IF;
IF g_bPlcResetBuffer THEN
  g_bDAOutputVolEnable:=FALSE;
  gas_type :=-1;
END_IF;
